//autogenerated:yes
//nolint:revive,govet,errcheck
package development_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/development"
)

func TestEnum_TARGET_ABSOLUTE_SENSOR_CAPABILITY_FLAGS(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.TARGET_ABSOLUTE_SENSOR_CAPABILITY_FLAGS
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.TARGET_ABSOLUTE_SENSOR_CAPABILITY_POSITION.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.TARGET_ABSOLUTE_SENSOR_CAPABILITY_FLAGS
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.TARGET_ABSOLUTE_SENSOR_CAPABILITY_POSITION, dec)
	})
}
